package io.github.jhipster.sample.web.rest.errors;

import jakarta.servlet.http.HttpServletRequest;
import java.net.URI;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.annotation.AnnotatedElementUtils;
import org.springframework.core.env.Environment;
import org.springframework.dao.ConcurrencyFailureException;
import org.springframework.dao.DataAccessException;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageConversionException;
import org.springframework.lang.Nullable;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.AuthenticationException;
import org.springframework.validation.BindingResult;
import org.springframework.web.ErrorResponse;
import org.springframework.web.ErrorResponseException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.context.request.NativeWebRequest;
import org.springframework.web.context.request.ServletWebRequest;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
import tech.jhipster.config.JHipsterConstants;
import tech.jhipster.web.util.HeaderUtil;

/**
 * Controller advice to translate the server side exceptions to client-friendly json structures.
 * The error response follows RFC7807 - Problem Details for HTTP APIs (https://tools.ietf.org/html/rfc7807).
 */
@ControllerAdvice
public class ExceptionTranslator extends ResponseEntityExceptionHandler {

    private static final String FIELD_ERRORS_KEY = "fieldErrors";
    private static final String MESSAGE_KEY = "message";
    private static final String PATH_KEY = "path";
    private static final URI DEFAULT_PROBLEM_TYPE = URI.create("about:blank");

    @Value("${jhipster.clientApp.name}")
    private String applicationName;

    private final Environment env;

    public ExceptionTranslator(Environment env) {
        this.env = env;
    }

    @ExceptionHandler
    public ResponseEntity<Object> handleAnyException(Throwable ex, NativeWebRequest request) {
        ProblemDetail problem = wrapAndCustomizeProblem(ex, request);
        return handleExceptionInternal((Exception) ex, problem, buildHeaders(ex), HttpStatusCode.valueOf(problem.getStatus()), request);
    }

    @Override
    protected ResponseEntity<Object> handleExceptionInternal(
        Exception ex,
        @Nullable Object body,
        HttpHeaders headers,
        HttpStatusCode statusCode,
        WebRequest request
    ) {
        body = body == null ? wrapAndCustomizeProblem(ex, (NativeWebRequest) request) : body;
        if (body instanceof ProblemDetail pd) {
            customizeProblem(pd, ex, (NativeWebRequest) request);
        }
        return super.handleExceptionInternal(ex, body, headers, statusCode, request);
    }

    protected ProblemDetail wrapAndCustomizeProblem(Throwable ex, NativeWebRequest request) {
        ProblemDetail problem = getProblemDetail(ex);
        return customizeProblem(problem, ex, request);
    }

    private ProblemDetail getProblemDetail(Throwable ex) {
        if (ex instanceof io.github.jhipster.sample.service.UsernameAlreadyUsedException) {
            return new LoginAlreadyUsedException().getBody();
        }
        if (ex instanceof io.github.jhipster.sample.service.EmailAlreadyUsedException) {
            return new EmailAlreadyUsedException().getBody();
        }
        if (ex instanceof io.github.jhipster.sample.service.InvalidPasswordException) {
            return new InvalidPasswordException().getBody();
        }
        if (ex instanceof ErrorResponse er) {
            return er.getBody();
        }
        if (ex instanceof AuthenticationException) {
            return ProblemDetail.forStatusAndDetail(HttpStatus.UNAUTHORIZED, ex.getMessage());
        }
        if (ex instanceof AccessDeniedException) {
            return ProblemDetail.forStatusAndDetail(HttpStatus.FORBIDDEN, ex.getMessage());
        }
        if (ex instanceof ConcurrencyFailureException) {
            ProblemDetail problem = ProblemDetail.forStatus(HttpStatus.CONFLICT);
            problem.setProperty(MESSAGE_KEY, ErrorConstants.ERR_CONCURRENCY_FAILURE);
            return problem;
        }
        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
        String reason = null;
        ResponseStatus responseStatus = AnnotatedElementUtils.findMergedAnnotation(ex.getClass(), ResponseStatus.class);
        if (responseStatus != null) {
            status = responseStatus.code();
            reason = StringUtils.isNotBlank(responseStatus.reason()) ? responseStatus.reason() : null;
        }
        ProblemDetail problem = ProblemDetail.forStatus(status);
        problem.setTitle(reason != null ? reason : status.getReasonPhrase());
        problem.setDetail(getCustomizedErrorDetails(ex));
        return problem;
    }

    protected ProblemDetail customizeProblem(ProblemDetail problem, Throwable err, NativeWebRequest request) {
        if (problem.getStatus() <= 0) {
            problem.setStatus(HttpStatus.INTERNAL_SERVER_ERROR.value());
        }
        if (problem.getType() == null || DEFAULT_PROBLEM_TYPE.equals(problem.getType())) {
            problem.setType(
                err instanceof MethodArgumentNotValidException ? ErrorConstants.CONSTRAINT_VIOLATION_TYPE : ErrorConstants.DEFAULT_TYPE
            );
        }
        HttpStatus status = HttpStatus.resolve(problem.getStatus());
        if (problem.getTitle() == null && status != null) {
            problem.setTitle(status.getReasonPhrase());
        }
        if (err instanceof MethodArgumentNotValidException) {
            problem.setTitle("Method argument not valid");
        }
        Map<String, Object> props = problem.getProperties();
        if (props == null || !props.containsKey(MESSAGE_KEY)) {
            problem.setProperty(
                MESSAGE_KEY,
                err instanceof MethodArgumentNotValidException ? ErrorConstants.ERR_VALIDATION : "error.http." + problem.getStatus()
            );
        }
        if (props == null || !props.containsKey(PATH_KEY)) {
            problem.setProperty(PATH_KEY, getPathValue(request));
        }
        if (err instanceof MethodArgumentNotValidException fieldException && (props == null || !props.containsKey(FIELD_ERRORS_KEY))) {
            problem.setProperty(FIELD_ERRORS_KEY, getFieldErrors(fieldException));
        }
        if (problem.getDetail() == null && !(err instanceof MethodArgumentNotValidException)) {
            String detail = getCustomizedErrorDetails(err);
            if (detail != null && !(err instanceof ErrorResponse)) {
                problem.setDetail(detail);
            }
        }
        return problem;
    }

    private String getCustomizedErrorDetails(Throwable err) {
        Collection<String> activeProfiles = Arrays.asList(env.getActiveProfiles());
        if (activeProfiles.contains(JHipsterConstants.SPRING_PROFILE_PRODUCTION)) {
            if (err instanceof HttpMessageConversionException) return "Unable to convert http message";
            if (err instanceof DataAccessException) return "Failure during data access";
            if (containsPackageName(err.getMessage())) return "Unexpected runtime exception";
        }
        return err.getCause() != null ? err.getMessage() + " " + err.getCause().getMessage() : err.getMessage();
    }

    private List<FieldErrorVM> getFieldErrors(MethodArgumentNotValidException ex) {
        BindingResult result = ex.getBindingResult();
        return result
            .getFieldErrors()
            .stream()
            .map(f ->
                new FieldErrorVM(
                    f.getObjectName().replaceFirst("DTO$", ""),
                    f.getField(),
                    StringUtils.isNotBlank(f.getDefaultMessage()) ? f.getDefaultMessage() : f.getCode()
                )
            )
            .collect(Collectors.toList());
    }

    private HttpHeaders buildHeaders(Throwable err) {
        if (err instanceof BadRequestAlertException ex) {
            return HeaderUtil.createFailureAlert(applicationName, true, ex.getEntityName(), ex.getErrorKey(), ex.getMessage());
        }
        if (err instanceof io.github.jhipster.sample.service.UsernameAlreadyUsedException) {
            LoginAlreadyUsedException p = new LoginAlreadyUsedException();
            return HeaderUtil.createFailureAlert(applicationName, true, p.getEntityName(), p.getErrorKey(), p.getMessage());
        }
        if (err instanceof io.github.jhipster.sample.service.EmailAlreadyUsedException) {
            EmailAlreadyUsedException p = new EmailAlreadyUsedException();
            return HeaderUtil.createFailureAlert(applicationName, true, p.getEntityName(), p.getErrorKey(), p.getMessage());
        }
        return null;
    }

    private String getPathValue(NativeWebRequest request) {
        if (request == null) return StringUtils.EMPTY;
        HttpServletRequest nativeRequest = request.getNativeRequest(HttpServletRequest.class);
        return nativeRequest != null ? nativeRequest.getRequestURI() : StringUtils.EMPTY;
    }

    private boolean containsPackageName(String message) {
        // This list is for sure not complete
        return StringUtils.containsAny(message, "org.", "java.", "net.", "jakarta.", "javax.", "com.", "io.", "de.", "io.github.jhipster.sample");
    }
}
